<?php require __DIR__.'/app/bootstrap.php';$s=db()->prepare("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.slug=? AND p.status='active'");$s->execute([$_GET['slug']??'']);$p=$s->fetch();if(!$p){http_response_code(404);exit('Product not found');}$pageTitle=$p['name'].' — NEXT TECH';require __DIR__.'/includes/header.php';?><section class="product-detail"><div class="detail-image"><?php if($p['image']):?><img src="<?=e(url('uploads/products/'.$p['image']))?>" alt="<?=e($p['name'])?>"><?php else:?><span>◇</span><?php endif;?></div><div class="detail-copy"><span class="eyebrow"><?=e($p['category_name']??'NEXT TECH')?></span><h1><?=e($p['name'])?></h1><p class="price large"><?=money($p['price'])?></p><p><?=nl2br(e($p['description']))?></p><p class="stock"><?=((int)$p['stock']>0)?'In Stock':'Out of Stock'?></p><?php if((int)$p['stock']>0):?><form method="post" action="<?=e(url('cart.php'))?>" class="product-buy-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><label>Quantity <input type="number" name="quantity" value="1" min="1" max="<?=(int)$p['stock']?>" class="qty-input"></label><button class="btn btn-primary" name="add" value="1">Add to Cart</button></form><?php endif;?><form method="post" action="<?=e(url('wishlist.php'))?>" class="wishlist-add"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><button class="btn btn-outline">♡ Save to Wishlist</button></form></div></section><?php require __DIR__.'/includes/footer.php';?>